return items.map(item => {
  // Try common field names automatically
  let text = item.json.output ?? item.json.text ?? item.json.response ?? '';

  if (!text) {
    // nothing to clean — return item as-is so the workflow doesn't break
    return item;
  }

  text = text.replace(/\*\*(.*?)\*\*/g, '$1');
  text = text.replace(/\*(.*?)\*/g, '$1');
  text = text.replace(/[\\*_~`#>]/g, '');
  text = text.replace(/^-\s+/gm, '→ ');
  text = text.split(/\n---\n/)[0];
  text = text.replace(/\n{3,}/g, '\n\n').trim();

  item.json.output = text; // normalize to "output" so downstream node is consistent
  return item;
});
